import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Award, BarChart3, CalendarDays, Check, Coffee, Crown, Download, Flame, FileText, Gauge, Home, Lock, Moon, Pencil, Plus, RefreshCw, Save, Send, Settings, Share2, Shield, Sparkles, Sun, Target, Trash2, Trophy, Upload, Users, Zap } from 'lucide-react';

const ROLES = ['Salesman', 'Supervisor', 'Manager-of-team', 'Sales Manager', 'General Manager'];
const ADMIN_ROLES = new Set(ROLES.slice(1));
const ADMIN_PIN_DEFAULT = '9999';
const MONTH = new Date().toISOString().slice(0, 7);
const uid = (p = 'id') => `${p}_${Math.random().toString(36).slice(2, 9)}_${Date.now().toString(36)}`;
const money = n => `OMR ${Math.round(Number(n || 0)).toLocaleString('en-OM')}`;
const pct = n => `${Number(n || 0).toFixed(1)}%`;
const toNum = v => Number.isFinite(Number(v)) ? Number(v) : 0;
const natural = (salesmanId, monthKey) => `${salesmanId}|${monthKey}`;
const slabKey = (regionId, monthKey) => `${regionId}|${monthKey}`;
const todayIso = () => new Date().toISOString().slice(0, 10);
const achievementBand = value => value >= 100 ? 'emerald' : value >= 75 ? 'lime' : value >= 50 ? 'amber' : 'rose';
const levelThresholds = [0, 250, 600, 1100, 1800, 2700, 3900, 5400, 7200, 9300, 11700];
const starterData = () => ({
  regions: [{ id: 'r_muscat', name: 'Muscat' }, { id: 'r_sohar', name: 'Sohar' }, { id: 'r_salalah', name: 'Salalah' }],
  teams: [{ id: 't_alpha', name: 'Alpha' }, { id: 't_beta', name: 'Beta' }],
  salesmen: [
    { id: 's_ali', name: 'Ali Hassan', pin: '1111', role: 'Salesman', active: true, defaultRegionId: 'r_muscat' },
    { id: 's_mona', name: 'Mona Said', pin: '1111', role: 'Salesman', active: true, defaultRegionId: 'r_sohar' },
    { id: 's_admin', name: 'General Manager', pin: ADMIN_PIN_DEFAULT, role: 'General Manager', active: true, defaultRegionId: 'r_muscat' }
  ],
  monthly: [
    { id: 'm_ali', salesmanId: 's_ali', monthKey: MONTH, regionId: 'r_muscat', teamId: 't_alpha', collectionTarget: 12000, salesTarget: 9000 },
    { id: 'm_mona', salesmanId: 's_mona', monthKey: MONTH, regionId: 'r_sohar', teamId: 't_beta', collectionTarget: 10000, salesTarget: 8000 },
    { id: 'm_admin', salesmanId: 's_admin', monthKey: MONTH, regionId: 'r_muscat', teamId: 't_alpha', collectionTarget: 0, salesTarget: 0 }
  ],
  openings: [{ id: 'o_ali', salesmanId: 's_ali', monthKey: MONTH, amount: 450 }],
  entries: [], challenges: [],
  slabs: [
    { id: 'sl1', regionMonthKey: slabKey('r_muscat', MONTH), name: 'Bronze', target: 6000, incentivePct: 1.25 },
    { id: 'sl2', regionMonthKey: slabKey('r_muscat', MONTH), name: 'Silver', target: 9000, incentivePct: 1.5 },
    { id: 'sl3', regionMonthKey: slabKey('r_muscat', MONTH), name: 'Gold', target: 12000, incentivePct: 2.0 },
    { id: 'sl4', regionMonthKey: slabKey('r_sohar', MONTH), name: 'Bronze', target: 5000, incentivePct: 1.0 }
  ],
  offDays: [], settings: { adminPin: ADMIN_PIN_DEFAULT, scriptUrl: '', dark: false }
});

function daysInMonth(monthKey) { const [y, m] = monthKey.split('-').map(Number); return new Date(y, m, 0).getDate(); }
function isoFor(monthKey, day) { return `${monthKey}-${String(day).padStart(2, '0')}`; }
function isFriday(iso) { return new Date(`${iso}T12:00:00`).getDay() === 5; }
function monthDays(monthKey) { return Array.from({ length: daysInMonth(monthKey) }, (_, i) => isoFor(monthKey, i + 1)); }
function isOff(data, iso) { return isFriday(iso) || data.offDays?.includes(iso); }
function workingDays(data, monthKey) { return monthDays(monthKey).filter(d => !isOff(data, d)); }
function monthEntries(data, salesmanId, monthKey) { return (data.entries || []).filter(e => e.salesmanId === salesmanId && e.date?.startsWith(monthKey)); }
function completedWorkingDays(data, salesmanId, monthKey) { const have = new Set(monthEntries(data, salesmanId, monthKey).map(e => e.date)); return workingDays(data, monthKey).filter(d => have.has(d)); }
function findAssignment(salesman, data, monthKey) { return (data.monthly || []).find(m => m.salesmanId === salesman.id && m.monthKey === monthKey) || { salesmanId: salesman.id, monthKey, regionId: salesman.defaultRegionId, teamId: '', collectionTarget: 0, salesTarget: 0 }; }
function openingFor(data, salesmanId, monthKey) { return toNum((data.openings || []).find(o => o.salesmanId === salesmanId && o.monthKey === monthKey)?.amount); }
function challengeFor(data, salesmanId, date) { return (data.challenges || []).find(c => c.salesmanId === salesmanId && c.date === date); }
function dailyTargetFor(type, assignment, data, monthKey, date, actualBefore) { const override = challengeFor(data, assignment.salesmanId, date); const key = type === 'collection' ? 'collectionTarget' : 'salesTarget'; if (override?.[key]) return toNum(override[key]); const remaining = workingDays(data, monthKey).filter(d => d >= date).length || 1; const monthly = toNum(assignment[key]); return Math.max(0, (monthly - actualBefore) / remaining); }

export function migrate(raw) {
  const base = { ...starterData(), ...(raw || {}) };
  base.regions = (base.regions || []).map(r => typeof r === 'string' ? { id: `r_${r.toLowerCase().replace(/\W+/g, '_')}`, name: r } : r);
  const regionByName = Object.fromEntries(base.regions.map(r => [String(r.name).toLowerCase(), r.id]));
  base.salesmen = (base.salesmen || []).map(s => ({ id: s.id || uid('s'), name: s.name || 'Unnamed', pin: String(s.pin || '1111'), role: s.role || 'Salesman', active: s.active !== false, defaultRegionId: s.defaultRegionId || regionByName[String(s.region || '').toLowerCase()] || base.regions[0]?.id }));
  const monthly = [];
  for (const row of (base.monthly || [])) {
    if (row.salesmanId) monthly.push({ id: row.id || uid('m'), salesmanId: row.salesmanId, monthKey: row.monthKey || row.month || MONTH, regionId: row.regionId || regionByName[String(row.region || '').toLowerCase()] || base.salesmen.find(s => s.id === row.salesmanId)?.defaultRegionId, teamId: row.teamId || '', collectionTarget: toNum(row.collectionTarget ?? row.target), salesTarget: toNum(row.salesTarget ?? row.sales) });
    else if (row.region || row.regionId) for (const s of base.salesmen.filter(x => (x.defaultRegionId === (row.regionId || regionByName[String(row.region || '').toLowerCase()])))) monthly.push({ id: uid('m'), salesmanId: s.id, monthKey: row.monthKey || row.month || MONTH, regionId: s.defaultRegionId, teamId: row.teamId || '', collectionTarget: toNum(row.collectionTarget ?? row.target), salesTarget: toNum(row.salesTarget ?? row.sales) });
  }
  base.monthly = Array.from(new Map(monthly.map(m => [natural(m.salesmanId, m.monthKey), m])).values());
  const openings = [...(base.openings || []).map(o => ({ id: o.id || uid('o'), salesmanId: o.salesmanId, monthKey: o.monthKey || o.month || MONTH, amount: toNum(o.amount ?? o.openingCheque) }))];
  for (const old of (raw?.monthly || [])) if (old.salesmanId && old.openingCheque != null && !openings.some(o => o.salesmanId === old.salesmanId && o.monthKey === (old.monthKey || old.month || MONTH))) openings.push({ id: uid('o'), salesmanId: old.salesmanId, monthKey: old.monthKey || old.month || MONTH, amount: toNum(old.openingCheque) });
  base.openings = openings.filter(o => o.salesmanId && o.monthKey);
  base.slabs = (base.slabs || []).map(sl => { const mk = sl.monthKey || (String(sl.regionMonthKey || '').includes('|') ? sl.regionMonthKey.split('|')[1] : sl.regionMonthKey) || MONTH; const rid = sl.regionId || base.regions[0]?.id; const pctVal = sl.incentivePct ?? (sl.incentiveAmount && sl.target ? (toNum(sl.incentiveAmount) / toNum(sl.target)) * 100 : 0); return { id: sl.id || uid('sl'), regionMonthKey: String(sl.regionMonthKey || '').includes('|') ? sl.regionMonthKey : slabKey(rid, mk), name: sl.name || 'Slab', target: toNum(sl.target), incentivePct: Number(toNum(pctVal).toFixed(2)) }; });
  base.entries = (base.entries || []).map(e => ({ id: e.id || uid('e'), salesmanId: e.salesmanId, date: e.date, collection: toNum(e.collection), sales: toNum(e.sales), visits: toNum(e.visits) })).filter(e => e.salesmanId && e.date);
  base.challenges = base.challenges || []; base.offDays = base.offDays || []; base.settings = { adminPin: ADMIN_PIN_DEFAULT, ...(base.settings || {}) };
  return base;
}

export function computePerf(salesman, data, monthKey) {
  const assignment = findAssignment(salesman, data, monthKey); const region = data.regions.find(r => r.id === assignment.regionId); const entries = monthEntries(data, salesman.id, monthKey).sort((a, b) => a.date.localeCompare(b.date));
  const opening = openingFor(data, salesman.id, monthKey); const totalCollection = entries.reduce((s, e) => s + toNum(e.collection), opening); const totalSales = entries.reduce((s, e) => s + toNum(e.sales), 0); const totalVisits = entries.reduce((s, e) => s + toNum(e.visits), 0);
  const wdays = workingDays(data, monthKey); const pastLimit = todayIso().startsWith(monthKey) ? todayIso() : isoFor(monthKey, daysInMonth(monthKey)); const elapsed = wdays.filter(d => d <= pastLimit).length || 1; const completed = completedWorkingDays(data, salesman.id, monthKey).length || 0;
  const dailyCollectionTarget = toNum(assignment.collectionTarget) / (wdays.length || 1); const dailySalesTarget = toNum(assignment.salesTarget) / (wdays.length || 1);
  let cBefore = opening, sBefore = 0; const dynTargetByDate = {}, streakHitByDate = {};
  for (const d of wdays) { const cTarget = dailyTargetFor('collection', assignment, data, monthKey, d, cBefore); const sTarget = dailyTargetFor('sales', assignment, data, monthKey, d, sBefore); dynTargetByDate[d] = { collection: cTarget, sales: sTarget }; const e = entries.find(x => x.date === d); const hit = !!e && toNum(e.collection) >= cTarget && toNum(e.sales) >= sTarget; streakHitByDate[d] = hit; if (e) { cBefore += toNum(e.collection); sBefore += toNum(e.sales); } }
  let walkDate = [...wdays].reverse().find(d => d <= todayIso() && (d <= todayIso() || entries.some(e => e.date === d))); let currentStreak = 0; for (const d of [...wdays].reverse().filter(d => !walkDate || d <= walkDate)) { if (streakHitByDate[d]) currentStreak++; else if (entries.some(e => e.date === d) || d <= todayIso()) break; }
  const collectionPct = toNum(assignment.collectionTarget) ? totalCollection / toNum(assignment.collectionTarget) * 100 : 0; const salesPct = toNum(assignment.salesTarget) ? totalSales / toNum(assignment.salesTarget) * 100 : 0;
  const expectedCollection = dailyCollectionTarget * elapsed; const expectedSales = dailySalesTarget * elapsed; const paceCollectionDelta = expectedCollection ? (totalCollection - expectedCollection) / expectedCollection * 100 : 0; const paceSalesDelta = expectedSales ? (totalSales - expectedSales) / expectedSales * 100 : 0;
  const forecastCollection = completed ? (totalCollection / completed) * wdays.length : 0; const forecastSales = completed ? (totalSales / completed) * wdays.length : 0;
  const slabs = (data.slabs || []).filter(s => s.regionMonthKey === slabKey(assignment.regionId, monthKey)).sort((a, b) => toNum(a.target) - toNum(b.target)); const achieved = slabs.filter(s => totalCollection >= toNum(s.target)); const winner = achieved.at(-1); const slabRows = slabs.map(s => ({ ...s, achieved: totalCollection >= toNum(s.target), isWinner: winner?.id === s.id, earnedIncentive: winner?.id === s.id ? toNum(s.incentivePct) / 100 * totalCollection : 0 }));
  const entryXp = entries.length * 10; const hitXp = Object.values(streakHitByDate).filter(Boolean).length * 20; const visitXp = Math.min(totalVisits * 5, entries.length * 50); const streakXp = currentStreak * 50; const slabXp = winner ? 200 : 0; const challengeXp = entries.filter(e => challengeFor(data, salesman.id, e.date)).length * 25; const xp = entryXp + hitXp + visitXp + streakXp + slabXp + challengeXp;
  const level = Math.min(11, levelThresholds.findIndex((t, i) => xp >= t && xp < (levelThresholds[i + 1] ?? Infinity)) + 1 || 11); const prev = levelThresholds[level - 1] ?? 0; const next = levelThresholds[level] ?? levelThresholds.at(-1); const levelPct = next === prev ? 100 : Math.min(100, (xp - prev) / (next - prev) * 100);
  const badges = []; [3, 7, 14, 21].forEach(n => currentStreak >= n && badges.push(`${n}-day streak`)); [50, 75, 100, 120].forEach(n => collectionPct >= n && badges.push(`${n}% target`)); if (winner) badges.push('Slab won'); [30, 50, 100].forEach(n => totalVisits >= n && badges.push(`${n} visits`)); [3, 6, 9, 11].forEach(n => level >= n && badges.push(`Level ${n}`)); if (entries.length >= 10 && Object.values(streakHitByDate).filter(Boolean).length / entries.length >= .8) badges.push('Consistency');
  return { regionId: assignment.regionId, teamId: assignment.teamId, region, assignment, targets: { collection: toNum(assignment.collectionTarget), sales: toNum(assignment.salesTarget) }, dailyTargets: { collection: dailyCollectionTarget, sales: dailySalesTarget }, actuals: { collection: totalCollection, sales: totalSales, visits: totalVisits, opening }, percentages: { collection: collectionPct, sales: salesPct }, pace: { expectedCollection, expectedSales, paceCollectionDelta, paceSalesDelta, elapsed, totalWorkingDays: wdays.length }, forecast: { collection: forecastCollection, sales: forecastSales, completedWorkingDays: completed }, dynTargetByDate, streakHitByDate, currentStreak, slabRows, highestAchievedId: winner?.id, totalEarnedIncentive: slabRows.reduce((s, r) => s + r.earnedIncentive, 0), badges, xp, level, levelPct, xpToNextLevel: Math.max(0, next - xp), entries };
}

function registerSW() { if ('serviceWorker' in navigator) navigator.serviceWorker.register('/sw.js').catch(() => {}); }
function readLocal() { try { return migrate(JSON.parse(localStorage.getItem('performance-ledger') || 'null')); } catch { return migrate(); } }
function saveLocal(data) { localStorage.setItem('performance-ledger', JSON.stringify(data)); }
async function cloud(url, action, payload) { if (!url) return null; const res = await fetch(url, { method: action === 'pull' ? 'GET' : 'POST', body: action === 'pull' ? undefined : JSON.stringify({ action, payload }), headers: action === 'pull' ? undefined : { 'Content-Type': 'text/plain;charset=utf-8' } }); return res.json(); }

function Login({ data, onLogin }) { const [name, setName] = useState('Ali Hassan'); const [pin, setPin] = useState('1111'); const names = data.salesmen.filter(s => s.active).map(s => s.name); function submit(e) { e.preventDefault(); const user = data.salesmen.find(s => s.name.toLowerCase() === name.toLowerCase()); const override = pin === (data.settings.adminPin || ADMIN_PIN_DEFAULT); if (user && (user.pin === pin || override)) onLogin({ id: user.id, admin: override || ADMIN_ROLES.has(user.role) }); }
  return <div className="min-h-screen bg-stone-100 p-4 text-stone-900 dark:bg-stone-950 dark:text-stone-100"><div className="mx-auto flex min-h-[90vh] max-w-md items-center"><form onSubmit={submit} className="card w-full p-6"><div className="mb-6 text-center"><div className="mx-auto mb-3 grid h-16 w-16 place-items-center rounded-3xl bg-stone-900 text-amber-50"><Gauge /></div><h1 className="serif text-4xl font-bold">Performance Ledger</h1><p className="text-sm tracking-[.35em] text-amber-700">track. measure. close.</p></div><label className="text-sm font-bold">Typed-name autocomplete</label><input className="input mt-1" list="salesmen" value={name} onChange={e => setName(e.target.value)} /><datalist id="salesmen">{names.map(n => <option key={n} value={n} />)}</datalist><label className="mt-4 block text-sm font-bold">PIN</label><input className="input mt-1" type="password" value={pin} onChange={e => setPin(e.target.value)} /><button className="btn btn-primary mt-5 w-full">Sign in</button><p className="mt-4 text-xs text-stone-500">Demo salesman PIN <b>1111</b>. Emergency admin PIN <b>9999</b>.</p></form></div></div> }
function StatCard({ title, icon: Icon, target, actual, percent }) { const band = achievementBand(percent); return <div className="card p-4"><div className="flex items-center justify-between"><span className="text-sm font-bold text-stone-500 dark:text-stone-400">{title}</span><Icon className="text-amber-600" /></div><div className="num mt-4 text-3xl font-black">{money(actual)}</div><div className="mt-1 text-sm">Target {money(target)}</div><div className="mt-3 h-2 rounded-full bg-stone-200 dark:bg-stone-800"><div className={`h-2 rounded-full bg-${band}-500`} style={{ width: `${Math.min(100, percent)}%` }} /></div><span className={`pill achievement-${band} mt-3 inline-block`}>{pct(percent)}</span></div> }
function Gamification({ perf }) { return <div className="card p-4"><div className="flex items-center gap-2"><Sparkles className="text-amber-600" /><h3 className="serif text-xl font-bold">Gamification</h3></div><div className="mt-3 flex items-end justify-between"><div><p className="num text-3xl font-black">{perf.xp} XP</p><p className="text-sm">Level {perf.level} · {perf.xpToNextLevel} XP to next</p></div><Trophy className="text-emerald-600" /></div><div className="mt-3 h-3 rounded-full bg-stone-200 dark:bg-stone-800"><div className="h-3 rounded-full bg-amber-500" style={{ width: `${perf.levelPct}%` }} /></div><div className="mt-3 flex flex-wrap gap-2">{perf.badges.map(b => <span className="pill border-amber-300 bg-amber-50 dark:border-amber-800 dark:bg-stone-800" key={b}><Award className="mr-1 inline h-3 w-3" />{b}</span>)}</div></div> }
function TodayEntry({ user, data, setData, monthKey, perf }) { const date = todayIso(); const existing = data.entries.find(e => e.salesmanId === user.id && e.date === date); const [form, setForm] = useState(existing || { collection: '', sales: '', visits: '' }); const blocked = isOff(data, date); function save() { if (blocked) return; upsertEntry(data, setData, { ...existing, ...form, salesmanId: user.id, date }); }
  return <div className="card p-4"><div className="flex items-center justify-between"><h3 className="serif text-xl font-bold">Today entry</h3>{blocked ? <Coffee className="text-amber-600" /> : <Pencil className="text-emerald-600" />}</div>{blocked ? <p className="mt-3 rounded-2xl bg-amber-100 p-3 text-sm dark:bg-stone-800">Entries are blocked on Fridays and admin-marked off-days. Enjoy coffee.</p> : <div className="mt-3 grid grid-cols-3 gap-2"><input className="input" placeholder="Collection" value={form.collection} onChange={e => setForm({ ...form, collection: e.target.value })} /><input className="input" placeholder="Sales" value={form.sales} onChange={e => setForm({ ...form, sales: e.target.value })} /><input className="input" placeholder="Visits" value={form.visits} onChange={e => setForm({ ...form, visits: e.target.value })} /><button onClick={save} className="btn btn-primary col-span-3"><Save className="mr-2 inline h-4 w-4" />Save today</button></div>}<p className="mt-3 text-xs">Today's dynamic targets: Collection {money(perf.dynTargetByDate[date]?.collection || perf.dailyTargets.collection)} · Sales {money(perf.dynTargetByDate[date]?.sales || perf.dailyTargets.sales)}</p></div> }
function Slabs({ perf }) { return <div className="card p-4"><h3 className="serif mb-3 text-xl font-bold">Sub-Collection Slabs</h3><div className="space-y-2">{perf.slabRows.map((s, i) => <div key={s.id} className={`flex items-center justify-between rounded-2xl border p-3 ${s.isWinner ? 'border-amber-400 bg-amber-50 dark:bg-stone-800' : 'border-stone-200 dark:border-stone-700'}`}><div><span className="text-xs font-black text-stone-500">TIER {i + 1}</span><p className="font-bold">{s.name} · {money(s.target)}</p></div><div className="text-right font-bold">{s.isWinner && <Crown className="mr-1 inline text-amber-500" />}{s.achieved && !s.isWinner ? <span className="line-through">{Number(s.incentivePct).toFixed(2)}%</span> : <span>{Number(s.incentivePct).toFixed(2)}%</span>}{s.isWinner && <span> → {money(s.earnedIncentive)}</span>}</div></div>)}</div></div> }
function upsertEntry(data, setData, entry) { const clean = { id: entry.id || uid('e'), salesmanId: entry.salesmanId, date: entry.date, collection: toNum(entry.collection), sales: toNum(entry.sales), visits: toNum(entry.visits) }; setData(d => ({ ...d, entries: [...d.entries.filter(e => e.id !== clean.id && !(e.salesmanId === clean.salesmanId && e.date === clean.date)), clean] })); }
async function shareReport(perf, entry) { const text = `*Performance Ledger*\n${entry.date}\nCollection: ${money(entry.collection)}\nSales: ${money(entry.sales)}\nVisits: ${entry.visits}\nTotal collection: ${money(perf.actuals.collection)}\nStreak: ${perf.streakHitByDate[entry.date] ? '🔥 hit' : 'not hit'}`; const canvas = document.createElement('canvas'); canvas.width = 720; canvas.height = 1100; const ctx = canvas.getContext('2d'); ctx.fillStyle = '#f5f5f4'; ctx.fillRect(0, 0, 720, 1100); ctx.fillStyle = '#1c1917'; ctx.font = 'bold 48px Georgia'; ctx.fillText('Performance Ledger', 48, 80); ctx.font = '26px Georgia'; ['track. measure. close.', entry.date, `Monthly collection target ${money(perf.targets.collection)}`, `Monthly sales target ${money(perf.targets.sales)}`, `Today dynamic collection ${money(perf.dynTargetByDate[entry.date]?.collection)}`, `Today earned ${money(entry.collection)} (${pct((entry.collection / (perf.dynTargetByDate[entry.date]?.collection || 1)) * 100 - 100)} variation)`, `Visits ${entry.visits}`, `Average collection ${money(perf.actuals.collection / Math.max(1, perf.forecast.completedWorkingDays))}`, `Total actual collection ${money(perf.actuals.collection)}`, `Next-day target ${money(perf.dynTargetByDate[monthDays(entry.date.slice(0,7)).find(d=>d>entry.date)]?.collection || 0)}`, perf.streakHitByDate[entry.date] ? '🔥 Streak hit' : 'Keep closing'].forEach((line, i) => ctx.fillText(line, 48, 150 + i * 70)); canvas.toBlob(async blob => { const file = new File([blob], 'performance-ledger.png', { type: 'image/png' }); if (navigator.canShare?.({ files: [file] })) await navigator.share({ files: [file], text }); else location.href = `https://wa.me/?text=${encodeURIComponent(text)}`; }); }
function Breakdown({ user, data, setData, perf, monthKey }) { const [edit, setEdit] = useState(null); const days = workingDays(data, monthKey); return <div className="card overflow-hidden"><div className="flex items-center justify-between p-4"><h3 className="serif text-xl font-bold">Daily Breakdown</h3><Flame className="text-rose-500" /></div><div className="overflow-x-auto"><table className="w-full text-sm"><thead className="bg-stone-200 dark:bg-stone-800"><tr><th className="p-2 text-left">Day</th><th>Dyn C</th><th>Dyn S</th><th>Collection</th><th>Sales</th><th>Visits</th><th>Actions</th></tr></thead><tbody>{days.map(d => { const e = data.entries.find(x => x.salesmanId === user.id && x.date === d); const hit = perf.streakHitByDate[d]; return <tr key={d} className={`border-t border-stone-200 dark:border-stone-800 ${hit ? 'border-l-4 border-l-emerald-500 bg-emerald-50/60 dark:bg-emerald-950/20' : ''}`}><td className="p-2 font-bold">{d} {hit && <Flame className="inline h-4 w-4 text-rose-500" />}</td><td className="num">{money(perf.dynTargetByDate[d]?.collection)}</td><td className="num">{money(perf.dynTargetByDate[d]?.sales)}</td><td className="num">{e ? money(e.collection) : '—'}</td><td className="num">{e ? money(e.sales) : '—'}</td><td className="num">{e?.visits ?? '—'}</td><td className="space-x-1 p-2">{!e && d <= todayIso() && <button className="btn btn-soft !px-2 !py-1" onClick={() => setEdit({ date: d, collection: '', sales: '', visits: '' })}><Plus className="h-4 w-4" /></button>}{e && <><button className="btn btn-soft !px-2 !py-1" onClick={() => setEdit(e)}><Pencil className="h-4 w-4" /></button><button className="btn btn-soft !px-2 !py-1" onClick={() => setData(x => ({ ...x, entries: x.entries.filter(row => row.id !== e.id) }))}><Trash2 className="h-4 w-4" /></button><button className="btn btn-soft !px-2 !py-1" onClick={() => shareReport(perf, e)}><Share2 className="h-4 w-4" /></button></>}</td></tr> })}</tbody></table></div>{edit && <div className="border-t p-4 dark:border-stone-800"><h4 className="font-bold">Entry for {edit.date}</h4><div className="mt-2 grid grid-cols-3 gap-2"><input className="input" placeholder="Collection" value={edit.collection} onChange={e => setEdit({ ...edit, collection: e.target.value })} /><input className="input" placeholder="Sales" value={edit.sales} onChange={e => setEdit({ ...edit, sales: e.target.value })} /><input className="input" placeholder="Visits" value={edit.visits} onChange={e => setEdit({ ...edit, visits: e.target.value })} /></div><button className="btn btn-primary mt-2" onClick={() => { upsertEntry(data, setData, { ...edit, salesmanId: user.id }); setEdit(null); }}>Save</button></div>}</div> }
function SalesmanDashboard({ auth, data, setData, monthKey }) { const user = data.salesmen.find(s => s.id === auth.id); const perf = computePerf(user, data, monthKey); useEffect(() => { if (perf.highestAchievedId) { const key = `confetti-${user.id}-${monthKey}-${perf.highestAchievedId}`; if (!localStorage.getItem(key)) { localStorage.setItem(key, '1'); document.body.animate([{ transform: 'scale(1)' }, { transform: 'scale(1.01)' }, { transform: 'scale(1)' }], 700); } } }, [perf.highestAchievedId]); return <div className="space-y-4"><div><h2 className="serif text-3xl font-bold">Hello, {user.name}</h2><p className="text-stone-500">{perf.region?.name} · {monthKey}</p></div><div className="grid gap-3 md:grid-cols-2"><StatCard title="Collection" icon={Target} target={perf.targets.collection} actual={perf.actuals.collection} percent={perf.percentages.collection} /><StatCard title="Sales" icon={BarChart3} target={perf.targets.sales} actual={perf.actuals.sales} percent={perf.percentages.sales} /></div><div className="grid gap-3 md:grid-cols-3"><div className="card p-4"><Gauge className="text-amber-600" /><h3 className="serif text-xl font-bold">Pace tracker</h3><p>Collection variation {pct(perf.pace.paceCollectionDelta)}</p><p>Sales variation {pct(perf.pace.paceSalesDelta)}</p></div><div className="card p-4"><Zap className="text-emerald-600" /><h3 className="serif text-xl font-bold">Forecast</h3><p>{money(perf.forecast.collection)} collection</p><p>{money(perf.forecast.sales)} sales</p><p className="text-xs">Formula: actual ÷ completed working days × total working days.</p></div><Gamification perf={perf} /></div><TodayEntry user={user} data={data} setData={setData} monthKey={monthKey} perf={perf} /><Slabs perf={perf} /><Breakdown user={user} data={data} setData={setData} perf={perf} monthKey={monthKey} /></div> }
function Field({ label, children }) { return <label className="block text-sm font-bold">{label}<div className="mt-1">{children}</div></label> }
function Admin({ data, setData, monthKey, setMonthKey }) { const [tab, setTab] = useState('Overview'); const tabs = ['Overview', 'Heatmap', 'Team', 'Assign', 'Opening', 'Calendar', 'Slabs', 'Challenge', 'Import', 'Reports', 'Settings']; return <div><div className="sticky top-0 z-10 -mx-4 mb-4 overflow-x-auto border-b border-stone-300 bg-stone-100/90 px-4 py-2 backdrop-blur dark:border-stone-700 dark:bg-stone-950/90"><div className="flex gap-2">{tabs.map(t => <button key={t} onClick={() => setTab(t)} className={`btn whitespace-nowrap !px-3 !py-2 ${tab === t ? 'btn-primary' : 'btn-soft'}`}>{t}</button>)}</div></div><div className="mb-4 flex gap-2"><input type="month" className="input max-w-48" value={monthKey} onChange={e => setMonthKey(e.target.value)} /><span className="pill border-stone-300">Admin workspace</span></div>{tab === 'Overview' && <Overview data={data} monthKey={monthKey} />}{tab === 'Heatmap' && <Heatmap data={data} monthKey={monthKey} />}{tab === 'Team' && <Team data={data} setData={setData} />}{tab === 'Assign' && <Assign data={data} setData={setData} monthKey={monthKey} />}{tab === 'Opening' && <Opening data={data} setData={setData} monthKey={monthKey} />}{tab === 'Calendar' && <CalendarAdmin data={data} setData={setData} monthKey={monthKey} />}{tab === 'Slabs' && <SlabAdmin data={data} setData={setData} monthKey={monthKey} />}{tab === 'Challenge' && <Challenge data={data} setData={setData} monthKey={monthKey} />}{tab === 'Import' && <Import data={data} setData={setData} monthKey={monthKey} />}{tab === 'Reports' && <Reports data={data} monthKey={monthKey} />}{tab === 'Settings' && <SettingsPane data={data} setData={setData} />}</div> }
function Overview({ data, monthKey }) { const [mode, setMode] = useState('region'); const rows = data.salesmen.filter(s => s.active).map(s => ({ s, p: computePerf(s, data, monthKey) })); const ranked = mode === 'individual' ? rows.sort((a,b)=>b.p.actuals.collection-a.p.actuals.collection) : Object.values(rows.reduce((acc, r) => { const key = r.p.regionId || 'none'; acc[key] ||= { name: r.p.region?.name || 'Unassigned', collection: 0, sales: 0, target: 0, forecast: 0 }; acc[key].collection += r.p.actuals.collection; acc[key].sales += r.p.actuals.sales; acc[key].target += r.p.targets.collection; acc[key].forecast += r.p.forecast.collection; return acc; }, {})); return <div className="card p-4"><div className="mb-3 flex justify-between"><h3 className="serif text-2xl font-bold">Leaderboard</h3><button className="btn btn-soft" onClick={()=>setMode(mode==='region'?'individual':'region')}>{mode}</button></div><div className="space-y-2">{ranked.map((r,i)=><div key={r.s?.id||r.name} className="rounded-2xl border border-stone-200 p-3 dark:border-stone-800"><b>#{i+1} {r.s?.name||r.name}</b><p>{money(r.p?.actuals.collection ?? r.collection)} collection · Forecast {money(r.p?.forecast.collection ?? r.forecast)}</p><div className="h-2 rounded bg-stone-200"><div className="h-2 rounded bg-emerald-500" style={{width:`${Math.min(100, r.p?.percentages.collection ?? (r.collection/(r.target||1))*100)}%`}} /></div></div>)}</div></div> }
function Heatmap({ data, monthKey }) { const days = workingDays(data, monthKey); return <div className="card overflow-x-auto p-4"><h3 className="serif text-2xl font-bold">Heatmap</h3><table className="mt-3 text-xs"><tbody>{data.salesmen.filter(s=>s.active).map(s=>{const p=computePerf(s,data,monthKey);return <tr key={s.id}><td className="sticky left-0 bg-stone-100 p-1 font-bold dark:bg-stone-900">{s.name}</td>{monthDays(monthKey).map(d=>{const e=data.entries.find(x=>x.salesmanId===s.id&&x.date===d); const val=e?(toNum(e.collection)/(p.dynTargetByDate[d]?.collection||1))*100:null; const color=d>todayIso()?'bg-stone-100':!e?'bg-rose-200':val>=100?'bg-emerald-500':val>=75?'bg-lime-400':val>=50?'bg-amber-400':'bg-rose-400'; return <td key={d} title={`${d} ${val?pct(val):''}`} className={`h-8 min-w-8 border border-white text-center ${color}`}>{d.slice(-2)}</td>})}</tr>})}</tbody></table></div> }
function Team({ data, setData }) { const blank = { name: '', pin: '1111', role: 'Salesman', active: true, defaultRegionId: data.regions[0]?.id }; const [s, setS] = useState(blank); function addSalesman(){setData(d=>({...d,salesmen:[...d.salesmen,{...s,id:uid('s')}]}));setS(blank)} return <div className="grid gap-4 md:grid-cols-3"><div className="card p-4"><h3 className="serif text-xl font-bold">Salesmen</h3><div className="space-y-2">{data.salesmen.map(x=><div key={x.id} className="rounded-xl border p-2 dark:border-stone-700"><b>{x.name}</b><p className="text-xs">{x.role} · {x.active?'active':'inactive'}</p></div>)}</div><div className="mt-3 grid gap-2"><input className="input" placeholder="Name" value={s.name} onChange={e=>setS({...s,name:e.target.value})}/><input className="input" placeholder="PIN" value={s.pin} onChange={e=>setS({...s,pin:e.target.value})}/><select className="input" value={s.role} onChange={e=>setS({...s,role:e.target.value})}>{ROLES.map(r=><option key={r}>{r}</option>)}</select><select className="input" value={s.defaultRegionId} onChange={e=>setS({...s,defaultRegionId:e.target.value})}>{data.regions.map(r=><option value={r.id} key={r.id}>{r.name}</option>)}</select><button className="btn btn-primary" onClick={addSalesman}>Add</button></div></div><SimpleList title="Teams" rows={data.teams} add={name=>setData(d=>({...d,teams:[...d.teams,{id:uid('t'),name}]}))}/><SimpleList title="Durable Regions" rows={data.regions} add={name=>setData(d=>({...d,regions:[...d.regions,{id:uid('r'),name}]}))} note="Deletion is blocked when active members exist and requires confirmation when historical entries exist."/></div> }
function SimpleList({ title, rows, add, note }) { const [name,setName]=useState(''); return <div className="card p-4"><h3 className="serif text-xl font-bold">{title}</h3>{rows.map(r=><p key={r.id} className="rounded-xl border p-2 dark:border-stone-700">{r.name}</p>)}<input className="input mt-2" value={name} onChange={e=>setName(e.target.value)} placeholder="Name"/><button className="btn btn-primary mt-2" onClick={()=>{if(name)add(name);setName('')}}>Add</button>{note&&<p className="mt-2 text-xs text-stone-500">{note}</p>}</div> }
function Assign({ data, setData, monthKey }) { function setMonthly(salesmanId, patch){setData(d=>{const old=d.monthly.find(m=>m.salesmanId===salesmanId&&m.monthKey===monthKey); const row={id:old?.id||uid('m'),salesmanId,monthKey,regionId:d.salesmen.find(s=>s.id===salesmanId)?.defaultRegionId,teamId:'',collectionTarget:0,salesTarget:0,...old,...patch}; return {...d,monthly:[...d.monthly.filter(m=>!(m.salesmanId===salesmanId&&m.monthKey===monthKey)),row]}})} function copyPrev(){const [y,m]=monthKey.split('-').map(Number); const prev=`${m===1?y-1:y}-${String(m===1?12:m-1).padStart(2,'0')}`; setData(d=>({...d,monthly:[...d.monthly.filter(x=>x.monthKey!==monthKey),...d.monthly.filter(x=>x.monthKey===prev).map(x=>({...x,id:uid('m'),monthKey}))]}))} return <div className="card overflow-x-auto p-4"><button className="btn btn-soft mb-3" onClick={copyPrev}><RefreshCw className="mr-1 inline h-4 w-4"/>Copy from previous month</button><table className="w-full text-sm"><tbody>{data.salesmen.filter(s=>s.active).map(s=>{const m=findAssignment(s,data,monthKey);return <tr key={s.id} className="border-t dark:border-stone-800"><td className="p-2 font-bold">{s.name}</td><td><select className="input" value={m.regionId||''} onChange={e=>setMonthly(s.id,{regionId:e.target.value})}>{data.regions.map(r=><option key={r.id} value={r.id}>{r.name}</option>)}</select></td><td><select className="input" value={m.teamId||''} onChange={e=>setMonthly(s.id,{teamId:e.target.value})}><option value="">No team</option>{data.teams.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select></td><td><input className="input" value={m.collectionTarget} onChange={e=>setMonthly(s.id,{collectionTarget:e.target.value})}/></td><td><input className="input" value={m.salesTarget} onChange={e=>setMonthly(s.id,{salesTarget:e.target.value})}/></td></tr>})}</tbody></table><p className="mt-3 text-xs">Inputs are local-focus guarded from cloud pulls for 10 seconds after each write.</p></div> }
function Opening({ data, setData, monthKey }) { const [dirty,setDirty]=useState({}); const [flash,setFlash]=useState(''); function save(sid){const amount=toNum(dirty[sid]); setData(d=>({...d,openings:[...d.openings.filter(o=>!(o.salesmanId===sid&&o.monthKey===monthKey)),{id:d.openings.find(o=>o.salesmanId===sid&&o.monthKey===monthKey)?.id||uid('o'),salesmanId:sid,monthKey,amount}]})); setDirty(x=>{const y={...x}; delete y[sid]; return y}); setFlash(sid); setTimeout(()=>setFlash(''),900)} return <div className="grid gap-3 md:grid-cols-2">{data.salesmen.filter(s=>s.active).map(s=>{const cur=openingFor(data,s.id,monthKey); const isDirty=dirty[s.id]!=null; return <div key={s.id} className={`card p-4 ${flash===s.id?'ring-2 ring-emerald-500':''}`}><b>{s.name}</b><p>Current opening PDC: {money(cur)}</p><div className="mt-2 flex gap-2"><input className="input" value={isDirty?dirty[s.id]:cur} onChange={e=>setDirty({...dirty,[s.id]:e.target.value})}/><button disabled={!isDirty} className={`btn ${isDirty?'btn-primary':'btn-soft opacity-50'}`} onClick={()=>save(s.id)}><Save/></button></div></div>})}</div> }
function CalendarAdmin({ data, setData, monthKey }) { return <div className="card p-4"><h3 className="serif text-2xl font-bold">Calendar off-days</h3><div className="mt-3 grid grid-cols-7 gap-2">{monthDays(monthKey).map(d=>{const off=data.offDays.includes(d);return <button key={d} onClick={()=>setData(x=>({...x,offDays:off?x.offDays.filter(v=>v!==d):[...x.offDays,d]}))} className={`rounded-2xl p-2 ${isFriday(d)||off?'bg-amber-200 dark:bg-amber-900':'bg-stone-200 dark:bg-stone-800'}`}>{d.slice(-2)}{isFriday(d)&&<Coffee className="mx-auto h-4 w-4"/>}</button>})}</div></div> }
function SlabAdmin({ data, setData, monthKey }) { const [region,setRegion]=useState(data.regions[0]?.id); const rows=data.slabs.filter(s=>s.regionMonthKey===slabKey(region,monthKey)); function add(){setData(d=>({...d,slabs:[...d.slabs,{id:uid('sl'),regionMonthKey:slabKey(region,monthKey),name:'New slab',target:0,incentivePct:1.50}]}))} function update(id,patch){setData(d=>({...d,slabs:d.slabs.map(s=>s.id===id?{...s,...patch}:s)}))} function applyAll(){setData(d=>({...d,slabs:[...d.slabs.filter(s=>!d.regions.some(r=>r.id!==region&&s.regionMonthKey===slabKey(r.id,monthKey))),...d.regions.filter(r=>r.id!==region).flatMap(r=>rows.map(s=>({...s,id:uid('sl'),regionMonthKey:slabKey(r.id,monthKey)})))]}))} return <div className="card p-4"><select className="input max-w-xs" value={region} onChange={e=>setRegion(e.target.value)}>{data.regions.map(r=><option key={r.id} value={r.id}>{r.name}</option>)}</select><div className="mt-3 grid gap-3 md:grid-cols-2">{rows.map((s,i)=><div key={s.id} className="rounded-3xl border p-4 dark:border-stone-700"><b className="text-xs">TIER {i+1}</b><input className="input mt-1" value={s.name} onChange={e=>update(s.id,{name:e.target.value})}/><input className="input mt-2" type="number" value={s.target} onChange={e=>update(s.id,{target:e.target.value})}/><input className="input mt-2" type="number" step="0.01" value={s.incentivePct} onChange={e=>update(s.id,{incentivePct:e.target.value})}/></div>)}</div><div className="mt-3 flex flex-wrap gap-2"><button className="btn btn-primary" onClick={add}>Add slab</button><button className="btn btn-soft" onClick={applyAll}>Apply to all regions</button><button className="btn btn-soft" onClick={()=>{}}>Copy from previous month</button></div></div> }
function Challenge({ data, setData, monthKey }) { const [c,setC]=useState({salesmanId:data.salesmen[0]?.id,date:isoFor(monthKey,1),collectionTarget:'',salesTarget:'',notes:''}); return <div className="card p-4"><h3 className="serif text-2xl font-bold">Daily challenge overrides</h3><div className="mt-3 grid gap-2 md:grid-cols-5"><select className="input" value={c.salesmanId} onChange={e=>setC({...c,salesmanId:e.target.value})}>{data.salesmen.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select><input className="input" type="date" value={c.date} onChange={e=>setC({...c,date:e.target.value})}/><input className="input" placeholder="Collection target" value={c.collectionTarget} onChange={e=>setC({...c,collectionTarget:e.target.value})}/><input className="input" placeholder="Sales target" value={c.salesTarget} onChange={e=>setC({...c,salesTarget:e.target.value})}/><input className="input" placeholder="Notes" value={c.notes} onChange={e=>setC({...c,notes:e.target.value})}/></div><button className="btn btn-primary mt-3" onClick={()=>setData(d=>({...d,challenges:[...d.challenges.filter(x=>!(x.salesmanId===c.salesmanId&&x.date===c.date)),{...c,id:uid('ch')}]}))}>Save challenge</button></div> }
function Import({ data, setData, monthKey }) { const [sid,setSid]=useState(data.salesmen[0]?.id); const [text,setText]=useState(''); const assigned=!!data.monthly.find(m=>m.salesmanId===sid&&m.monthKey===monthKey); const rows=text.trim().split(/\n/).filter(Boolean).map((line,i)=>{const [date,collection,sales,visits]=line.split(/[\t,]/); const iso=/^\d{4}-\d{2}-\d{2}$/.test(date)?date:isoFor(monthKey,Number(date)); return {i,date:iso,collection:toNum(collection),sales:toNum(sales),visits:toNum(visits),error:!iso.startsWith(monthKey)||!collection?'Invalid row':''}}); return <div className="card p-4"><h3 className="serif text-2xl font-bold">Bulk import</h3><select className="input mt-2 max-w-xs" value={sid} onChange={e=>setSid(e.target.value)}>{data.salesmen.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select>{!assigned&&<p className="mt-2 rounded-2xl bg-rose-100 p-3 text-sm text-rose-800">Import disabled: no region assignment exists for this salesman and month.</p>}<textarea className="input mt-2 min-h-40" value={text} onChange={e=>setText(e.target.value)} placeholder="date, collection, sales, visits"/><p className="mt-2">Rows {rows.length}; totals {money(rows.reduce((s,r)=>s+r.collection,0))}</p><button disabled={!assigned||rows.some(r=>r.error)} className="btn btn-primary mt-2 disabled:opacity-50" onClick={()=>setData(d=>({...d,entries:[...d.entries,...rows.map(r=>({id:uid('e'),salesmanId:sid,date:r.date,collection:r.collection,sales:r.sales,visits:r.visits}))]}))}>Import rows</button><pre className="mt-3 overflow-auto rounded-2xl bg-stone-200 p-3 text-xs dark:bg-stone-800">{JSON.stringify(rows,null,2)}</pre></div> }
function Reports({ data, monthKey }) { const csv=['salesman,region,collection,sales,visits,forecast'].concat(data.salesmen.map(s=>{const p=computePerf(s,data,monthKey);return [s.name,p.region?.name,p.actuals.collection,p.actuals.sales,p.actuals.visits,p.forecast.collection].join(',')})).join('\n'); return <div className="card p-4"><h3 className="serif text-2xl font-bold">Reports</h3><p>Compare up to three salesmen, drill into 3 months, export CSV, or print to PDF.</p><div className="mt-3 grid gap-3 md:grid-cols-3">{data.salesmen.slice(0,3).map(s=>{const p=computePerf(s,data,monthKey);return <div className="rounded-2xl border p-3 dark:border-stone-700" key={s.id}><b>{s.name}</b><p>{money(p.actuals.collection)} collection</p><p>{pct(p.percentages.collection)}</p></div>})}</div><textarea className="input mt-3 min-h-40 font-mono text-xs" readOnly value={csv}/><button className="btn btn-soft mt-2" onClick={()=>window.print()}><FileText className="mr-1 inline h-4 w-4"/>Print / PDF</button></div> }
function SettingsPane({ data, setData }) { const [deferred,setDeferred]=useState(null); useEffect(()=>{const f=e=>{e.preventDefault();setDeferred(e)}; window.addEventListener('beforeinstallprompt',f); return()=>window.removeEventListener('beforeinstallprompt',f)},[]); function setSetting(k,v){setData(d=>({...d,settings:{...d.settings,[k]:v}}))} return <div className="card p-4"><h3 className="serif text-2xl font-bold">Settings</h3><div className="mt-3 grid gap-3"><Field label="Apps Script endpoint"><input className="input" value={data.settings.scriptUrl||''} onChange={e=>setSetting('scriptUrl',e.target.value)} /></Field><Field label="Admin PIN"><input className="input" value={data.settings.adminPin} onChange={e=>setSetting('adminPin',e.target.value)} /></Field><button className="btn btn-soft" onClick={()=>setSetting('dark',!data.settings.dark)}>{data.settings.dark?<Sun/>:<Moon/>} Toggle light / dark</button><button className="btn btn-primary" onClick={()=>deferred?.prompt?.()} disabled={!deferred}>PWA install hint</button><p className="text-sm text-stone-500">If the prompt is unavailable: Chrome uses the address-bar install icon; Safari uses Share → Add to Home Screen.</p></div></div> }
export default function App() { const [data, rawSetData] = useState(readLocal); const [auth, setAuth] = useState(() => JSON.parse(sessionStorage.getItem('pl-auth') || 'null')); const [monthKey, setMonthKey] = useState(MONTH); const pendingWritesRef = useRef(0); const setData = updater => { pendingWritesRef.current = Date.now() + 10000; rawSetData(d => migrate(typeof updater === 'function' ? updater(d) : updater)); };
  useEffect(registerSW, []); useEffect(()=>{saveLocal(data); document.documentElement.classList.toggle('dark', !!data.settings.dark); if (pendingWritesRef.current > Date.now()) cloud(data.settings.scriptUrl, 'saveAll', data).catch(()=>{});},[data]); useEffect(()=>{sessionStorage.setItem('pl-auth', JSON.stringify(auth));},[auth]); useEffect(()=>{async function pull(){ if (pendingWritesRef.current > Date.now()) return; const remote=await cloud(data.settings.scriptUrl,'pull').catch(()=>null); if(remote?.data) rawSetData(migrate(remote.data)); } const handler=()=>{if(document.visibilityState==='visible')pull()}; window.addEventListener('focus',pull); document.addEventListener('visibilitychange',handler); return()=>{window.removeEventListener('focus',pull);document.removeEventListener('visibilitychange',handler)}},[data.settings.scriptUrl]);
  if (!auth) return <Login data={data} onLogin={setAuth} />; const user = data.salesmen.find(s=>s.id===auth.id); const isAdmin = auth.admin || ADMIN_ROLES.has(user?.role); return <div className="min-h-screen bg-stone-100 text-stone-900 dark:bg-stone-950 dark:text-stone-100"><header className="mx-auto flex max-w-6xl items-center justify-between p-4"><div><h1 className="serif text-3xl font-black">Performance Ledger</h1><p className="text-xs tracking-[.35em] text-amber-700">track. measure. close.</p></div><div className="flex gap-2"><button className="btn btn-soft" onClick={()=>setAuth(null)}><Lock className="h-4 w-4"/></button>{isAdmin&&<button className="btn btn-primary" onClick={()=>setAuth({...auth, admin:!auth.admin})}>{auth.admin?<Home/>:<Shield/>}</button>}</div></header><main className="mx-auto max-w-6xl p-4">{isAdmin && auth.admin ? <Admin data={data} setData={setData} monthKey={monthKey} setMonthKey={setMonthKey}/> : <SalesmanDashboard auth={auth} data={data} setData={setData} monthKey={monthKey}/>}</main></div> }
